package vault

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"strings"
	"testing"

	"github.com/arkade-os/emulator/pkg/arkade"
	"github.com/btcsuite/btcd/btcec/v2"
	"github.com/btcsuite/btcd/btcutil/psbt"
	"github.com/btcsuite/btcd/wire"
)

// Fixture PSBTs from arkade-wallet-vault src/lib/vault/v5 (commit d299463).
// Regenerated by building the savings-hardware initiate and phone clawback
// PSBTs from V5_FIXTURE_FAMILY.
const (
	v5VaultBaseHex = "03499fdf9e895e719cfd64e67f07d38e3226aa7b63678949e6e49b241a60e823e4"
	v5InitiatePSBT = ""
	v5ClawbackPSBT = ""
)

func TestV5TransitionScriptsExecuteOnEmulator(t *testing.T) {
	t.Parallel()
	base := mustPub(t, v5VaultBaseHex)
	for _, name := range []string{"initiate", "clawback"} {
		raw := v5InitiatePSBT
		if name == "clawback" {
			raw = v5ClawbackPSBT
		}
		ptx := mustPSBT(t, raw)
		if err := executeV5Transition(ptx, base); err != nil {
			t.Fatalf("%s: honest transition rejected: %v", name, err)
		}
	}
}

func TestV5TransitionScriptsRejectMutations(t *testing.T) {
	t.Parallel()
	base := mustPub(t, v5VaultBaseHex)
	ptx := mustPSBT(t, v5InitiatePSBT)
	if err := executeV5Transition(ptx, base); err != nil {
		t.Fatalf("honest initiate: %v", err)
	}

	wrongDest := cloneV5PSBT(t, ptx)
	wrongDest.UnsignedTx.TxOut[0].PkScript[10] ^= 0x01
	if err := executeV5Transition(wrongDest, base); err == nil {
		t.Fatal("accepted a mutated destination")
	}

	wrongP2A := cloneV5PSBT(t, ptx)
	wrongP2A.UnsignedTx.TxOut[1].Value = 0
	if err := executeV5Transition(wrongP2A, base); err == nil {
		t.Fatal("accepted a zero-value P2A")
	}

	finalSeq := cloneV5PSBT(t, ptx)
	finalSeq.UnsignedTx.TxIn[0].Sequence = wire.MaxTxInSequenceNum
	if err := executeV5Transition(finalSeq, base); err == nil {
		t.Fatal("accepted a final sequence")
	}

	droppedPacket := cloneV5PSBT(t, ptx)
	droppedPacket.UnsignedTx.TxOut = droppedPacket.UnsignedTx.TxOut[:2]
	if err := executeV5Transition(droppedPacket, base); err == nil {
		t.Fatal("accepted a packetless transition")
	}
}

func executeV5Transition(ptx *psbt.Packet, base *btcec.PublicKey) error {
	packet, err := arkade.FindEmulatorPacket(ptx.UnsignedTx)
	if err != nil {
		return err
	}
	if len(packet) != 1 {
		return fmt.Errorf("expected one emulator entry")
	}
	script, err := arkade.ReadArkadeScript(ptx, base, packet[0])
	if err != nil {
		return err
	}
	prev := ptx.Inputs[0].WitnessUtxo
	fetcher := NewPrevFetcher(ptx.UnsignedTx.TxIn[0].PreviousOutPoint, prev)
	return script.Execute(ptx.UnsignedTx, fetcher, 0)
}

func mustPSBT(t *testing.T, h string) *psbt.Packet {
	t.Helper()
	raw, err := hex.DecodeString(h)
	if err != nil {
		t.Fatal(err)
	}
	ptx, err := psbt.NewFromRawBytes(bytes.NewReader(raw), false)
	if err != nil {
		t.Fatal(err)
	}
	return ptx
}

func mustPub(t *testing.T, h string) *btcec.PublicKey {
	t.Helper()
	raw, err := hex.DecodeString(h)
	if err != nil {
		t.Fatal(err)
	}
	pub, err := btcec.ParsePubKey(raw)
	if err != nil {
		t.Fatal(err)
	}
	return pub
}

func cloneV5PSBT(t *testing.T, src *psbt.Packet) *psbt.Packet {
	t.Helper()
	raw, err := src.B64Encode()
	if err != nil {
		t.Fatal(err)
	}
	ptx, err := psbt.NewFromRawBytes(strings.NewReader(raw), true)
	if err != nil {
		t.Fatal(err)
	}
	return ptx
}
